struct Item {Vector2 p; int kind; bool taken=false;};
struct Enemy {float x,y,origin,phase;};
enum Screen {MENU,SELECT,PLATFORM,TRUCK};
int main(){InitWindow(1100,650,"Food Truck Fantasy - Prototype");SetTargetFPS(60);Screen screen=MENU;int girl=0,level=0,unlocked=0,money=30,served=0,hearts=3;int inv[4]={0,0,0,0};float px=65,py=420,vy=0,invincible=0;bool ground=false;vector<Item> items;vector<Enemy> enemies;float worldW=2200,cameraX=0;int customer=0;string notice="Welcome to Food Truck Fantasy!";float noticeTime=4;
 auto load=[&](int l){level=l;px=65;py=420;vy=0;hearts=3;invincible=0;items.clear();enemies.clear();for(int i=0;i<26;i++){int k=(i+l)%4;items.push_back({{150.0f+i*76.0f, (float)(i%5==0?310:i%3==0?375:455)},k,false});}for(int i=0;i<8;i++)enemies.push_back({360.0f+i*225,476.0f,360.0f+i*225,(float)i});screen=PLATFORM;};
 while(!WindowShouldClose()){float dt=min(GetFrameTime(),0.04f);if(noticeTime>0)noticeTime-=dt;Vector2 mouse=GetMousePosition();bool click=IsMouseButtonPressed(MOUSE_BUTTON_LEFT);auto button=[&](Rectangle r,const char* label,Color col)->bool{bool hover=CheckCollisionPointRec(mouse,r);DrawRectangleRounded(r,.24f,8,hover?Fade(col,.75f):col);DrawRectangleRoundedLinesEx(r,.24f,8,2,WHITE);int fs=22;DrawText(label,(int)(r.x+(r.width-MeasureText(label,fs))/2),(int)(r.y+(r.height-fs)/2),fs,WHITE);return hover&&click;};
 BeginDrawing();ClearBackground(Color{255,239,239,255});
 if(screen==MENU){DrawRectangleGradientV(0,0,1100,650,Color{255,190,219,255},Color{255,244,203,255});DrawText("FOOD TRUCK FANTASY",192,92,48,Color{121,54,109,255});DrawText("Four friends. Magical ingredients. One delicious dream!",215,160,23,DARKPURPLE);for(int i=0;i<4;i++){int x=225+i*175;DrawCircle(x+36,292,34,girls[i].hair);DrawCircle(x+36,299,24,Color{255,221,192,255});DrawCircle(x+27,296,3,BLACK);DrawCircle(x+46,296,3,BLACK);DrawRectangleRounded({(float)x,328,72,86},.3f,8,girls[i].outfit);DrawText(girls[i].name,x+4,432,22,DARKPURPLE);}if(button({405,510,290,65},"START GAME",Color{219,92,140,255}))screen=TRUCK;}
 if(screen==SELECT){DrawText("CHOOSE A FOOD WORLD",240,45,40,DARKPURPLE);const char* names[]={"Candy Meadow","Bakery Heights","Fruit Forest","Frozen Treats"};for(int i=0;i<4;i++){Rectangle r={180.0f+(i%2)*390,155.0f+(i/2)*150,345,110};string s=string(names[i])+(i>unlocked?" [LOCKED]":"");if(button(r,s.c_str(),i>unlocked?GRAY:Color{225,112,155,255})&&i<=unlocked)load(i);}if(button({380,510,340,55},"BACK TO FOOD TRUCK",Color{101,147,181,255}))screen=TRUCK;}
 if(screen==PLATFORM){float move=(IsKeyDown(KEY_D)||IsKeyDown(KEY_RIGHT)?1.0f:0.0f)-(IsKeyDown(KEY_A)||IsKeyDown(KEY_LEFT)?1.0f:0.0f);px=Clamp(px+move*girls[girl].speed*dt,15.0f,worldW-35);if((IsKeyPressed(KEY_SPACE)||IsKeyPressed(KEY_W)||IsKeyPressed(KEY_UP))&&ground){vy=-girls[girl].jump;ground=false;}float oldBottom=py+46;vy+=930*dt;py+=vy*dt;ground=false;if(py>=454){py=454;vy=0;ground=true;}for(int i=0;i<9;i++){Rectangle p={(float)(240+i*225), (float)(i%2?405:355),105,16};if(vy>=0&&px+28>p.x&&px<p.x+p.width&&oldBottom<=p.y+6&&py+46>=p.y){py=p.y-46;vy=0;ground=true;}}cameraX=Clamp(px-370,0.0f,worldW-1100);Color sky[4]={{255,218,229,255},{252,225,191,255},{211,242,198,255},{199,229,255,255}};ClearBackground(sky[level]);for(int i=0;i<24;i++){float x=i*115-cameraX;DrawCircle((int)x,520,58,Color{251,186,204,255});DrawCircle((int)x,525,42,Color{255,237,191,255});}DrawRectangle(0,500,1100,150,Color{141,205,132,255});for(int i=0;i<9;i++){float x=240+i*225-cameraX;DrawRectangleRounded({x,(float)(i%2?405:355),105,16},.5f,8,Color{169,97,69,255});DrawRectangle((int)x,(i%2?402:352),105,7,Color{255,238,189,255});}
 for(auto &it:items){if(it.taken)continue;float x=it.p.x-cameraX;Color colors[4]={RED,ORANGE,YELLOW,GREEN};DrawCircle((int)x,(int)it.p.y,13,colors[it.kind]);DrawCircle((int)x-4,(int)it.p.y-4,4,WHITE);if(fabs(px-it.p.x)<27&&fabs(py+20-it.p.y)<40){it.taken=true;inv[it.kind]++;}}
 for(auto &e:enemies){e.phase+=dt*1.8f;e.x=e.origin+sinf(e.phase)*55;float x=e.x-cameraX;DrawCircle((int)x,480,20,Color{147,80,148,255});DrawCircle((int)x-6,476,3,WHITE);DrawCircle((int)x+6,476,3,WHITE);if(invincible<=0&&fabs(px+14-e.x)<32&&fabs(py+24-e.y)<39){hearts--;invincible=1.4f;vy=-240;if(hearts<=0){notice="Out of hearts! Try the level again.";noticeTime=3;load(level);}}}invincible=max(0.0f,invincible-dt);
 float x=px-cameraX;Girl g=girls[girl];if(invincible<=0||((int)(GetTime()*12)%2==0)){DrawRectangleRounded({x,py+20,28,28},.35f,8,g.outfit);DrawCircle((int)x+14,(int)py+13,16,g.hair);DrawCircle((int)x+14,(int)py+17,11,Color{255,224,196,255});DrawCircle((int)x+10,(int)py+16,2,BLACK);DrawCircle((int)x+19,(int)py+16,2,BLACK);}
 DrawRectangle(0,0,1100,80,Fade(WHITE,.87f));DrawText(TextFormat("%s  |  Hearts: %d  |  Ingredients: %d %d %d %d",g.name,hearts,inv[0],inv[1],inv[2],inv[3]),18,18,22,DARKPURPLE);DrawText("A/D move  SPACE jump  TAB switch girl",18,50,18,DARKGRAY);if(px>worldW-95){unlocked=max(unlocked,min(level+1,3));notice="Level cleared! New world unlocked.";noticeTime=4;screen=TRUCK;}if(button({865,94,210,48},"RETURN TO TRUCK",Color{200,98,139,255}))screen=TRUCK;if(IsKeyPressed(KEY_TAB))girl=(girl+1)%4;}
 if(screen==TRUCK){ClearBackground(Color{239,247,255,255});DrawRectangle(0,455,1100,195,Color{173,205,163,255});DrawRectangleRounded({85,105,600,350},.1f,8,Color{255,169,194,255});DrawRectangleRounded({120,135,520,80},.2f,8,Color{255,246,198,255});DrawText("MAGICAL BITES",200,155,40,Color{135,67,111,255});DrawRectangleRounded({175,240,410,140},.2f,8,Color{255,250,235,255});DrawText("ORDER WINDOW",245,260,27,DARKPURPLE);DrawCircle(205,445,38,DARKGRAY);DrawCircle(570,445,38,DARKGRAY);DrawCircle(205,445,17,LIGHTGRAY);DrawCircle(570,445,17,LIGHTGRAY);DrawText("FOOD TRUCK BUSINESS",715,35,28,DARKPURPLE);DrawText(TextFormat("Cash: $%d",money),740,90,28,DARKGREEN);DrawText(TextFormat("Customers served: %d",served),740,135,23,DARKPURPLE);DrawText(TextFormat("Stock: %d red, %d orange",inv[0],inv[1]),715,178,19,DARKGRAY);DrawText(TextFormat("       %d yellow, %d green",inv[2],inv[3]),715,205,19,DARKGRAY);DrawText("Recipes (each needs 2 ingredients):",710,255,18,DARKPURPLE);
 if(button({710,290,345,48},"Fruit Cup  (red+green) $12",Color{213,95,128,255})){if(inv[0]>0&&inv[3]>0){inv[0]--;inv[3]--;money+=12;served++;customer++;notice="Fruit cup sold! +$12";}else notice="Missing ingredients! Visit a world.";noticeTime=3;}
 if(button({710,350,345,48},"Sweet Roll (orange+yellow) $16",Color{229,151,67,255})){if(inv[1]>0&&inv[2]>0){inv[1]--;inv[2]--;money+=16;served++;customer++;notice="Sweet roll sold! +$16";}else notice="Missing ingredients! Visit a world.";noticeTime=3;}
 if(button({710,425,345,48},"GO COLLECT INGREDIENTS",Color{121,153,206,255}))screen=SELECT;
 for(int i=0;i<4;i++){int xx=130+i*130;DrawCircle(xx,550,25,girls[i].hair);DrawCircle(xx,558,17,Color{255,223,195,255});DrawRectangleRounded({(float)xx-22,577,44,45},.3f,8,girls[i].outfit);DrawText(girls[i].name,xx-24,627,17,DARKPURPLE);}if(button({745,510,285,46},"SWITCH GIRL",Color{147,108,184,255}))girl=(girl+1)%4;DrawText(TextFormat("Selected: %s",girls[girl].name),760,568,23,DARKPURPLE);}
 if(noticeTime>0){DrawRectangleRounded({200,592,700,42},.3f,8,Fade(DARKPURPLE,.86f));DrawText(notice.c_str(),225,601,20,WHITE);}EndDrawing();}
 CloseWindow();return 0;}
